    {
      "title": "Java Compilation and Execution Flow",
      "source_segment_ids": ["FCT_0066", "FCT_0067", "FCT_0068", "FCT_0069", "FCT_0070", "FCT_0072", "FCT_0074"],
      "mode": "visual_only",
